const integrityLabels:Record<string,[string,string]>={verified:['已与归档原文核对 hash','success'],mismatch:['hash 核对失败 · 不可信','danger'],'not-checked':['原文过大，未核对','neutral']};
/** Side by side: the archived original (paged) and the exact view the host request carried. */
