  const pin=async()=>{const next=!event.pinned;setBusy(true);setActionError('');setActionMessage('');try{await command('pin',{scopeId,eventId,pinned:next});window.dispatchEvent(new Event('cmm-evidence-changed'));await detail.load();setActionMessage(next?'已固定此事件，它现在受到保护。':'已解除事件固定；链保护和近期召回仍可能继续保护它。');}catch(e){setActionError(errorText(e));}finally{setBusy(false);}};
  const dialog=useRef<HTMLElement>(null);
