function Highlighted({text,start,length}:{text:string;start:number;length:number}) {
  if(start<0||!length||start>=text.length)return <>{text}</>;
  return <>{text.slice(0,start)}<mark>{text.slice(start,start+length)}</mark>{text.slice(start+length)}</>;
}
function DownloadButton({scopeId,eventId,field,bytes:size}:{scopeId:string;eventId:string;field:string;bytes?:number}) {
  const [busy,setBusy]=useState(false),[error,setError]=useState('');
  const tooLarge=typeof size==='number'&&size>DOWNLOAD_LIMIT;
  const run=async()=>{setBusy(true);setError('');try{const file=await download(scopeId,eventId,field);saveBlob(file.blob,file.filename);}catch(e){setError(errorText(e));}finally{setBusy(false);}};
  return <div className="download-box"><button disabled={busy||tooLarge} onClick={()=>void run()} aria-describedby={tooLarge?'download-limit':undefined}>{busy?'正在读取…':'↓ 下载 UTF-8 原文'}</button>{tooLarge&&<small id="download-limit">原文 {bytes(size)} 超过 32 MiB 下载上限，请使用下方分页浏览或 context_recall 参数读取。</small>}{error&&<Alert tone="error">{error}</Alert>}</div>;
}
function RecordCards({title,records,empty='此事件没有这类记录。'}:{title:string;records:Data[];empty?:string}) {return <div className="record-section"><h3>{title}</h3>{records.length?records.map((r,i)=><div className="record-card" key={r.id??i}><Facts data={r}/></div>):<p className="muted">{empty}</p>}</div>;}
