  return <><Alert>这里展示工具证据会话，不是完整人类对话。链的 completed / frozen 不表示任务验收成功。</Alert><Card title="会话与关联链"><div className="tabs">{[['sessions','证据会话'],['chains','关联链']].map(([k,t])=><button key={k} className={kind===k?'active':''} onClick={()=>setKind(k)}>{t}</button>)}</div><RequestState {...list} retry={()=>void list.load()}/><div className="table-wrap"><table><thead><tr><th title={kind==='sessions'?'由 Agent、工作区和宿主会话 ID 派生的哈希；宿主原始会话 ID 不单独保存':undefined}>{kind==='sessions'?'归档会话 ID（宿主会话的哈希）':'关联链 ID'}</th><th>状态 / 事件数</th>{kind==='sessions'&&<th>CMM 压缩</th>}<th>创建时间</th><th>最后活动</th><th/></tr></thead><tbody>{list.data?.items?.map((s:Data)=><tr key={s.id} className={selected===s.id?'selected-row':''}><td><code>{s.id}</code></td><td>{s.status?`${stateLabel(s.status)} · ${number(s.eventCount)} 个事件`:`${number(s.eventCount)} 个事件 · 工具轮次 ${s.currentTurn??'—'}`}</td>{kind==='sessions'&&<td>{s.projectedEvents?<><Badge tone="success">已压缩 {number(s.projectedEvents)} 条 · −{reduction(s.originalChars,s.visibleChars)}%</Badge><small>{chars(s.originalChars)} → {chars(s.visibleChars)}</small></>:<Badge>未压缩</Badge>}</td>}<td>{time(s.createdAt??s.created_at)}</td><td>{time(s.updatedAt??s.lastActive??s.lastActivityAt??s.last_seen_at)}</td><td><button className="text-button" onClick={()=>setSelected(selected===s.id?null:s.id)}>{selected===s.id?'收起':'打开'} →</button></td></tr>)}</tbody></table></div>{!list.loading&&list.data&&!list.data.items?.length&&<Empty title={kind==='sessions'?'此范围暂无证据会话':'此范围暂无关联链'}>{kind==='sessions'?'宿主捕获工具结果后会出现对应会话。':'关联链在相关工具证据被识别后建立。'}</Empty>}<Pagination previous={previous} setPrevious={setPrevious} cursor={cursor} setCursor={setCursor} next={list.data?.nextCursor} loading={list.loading}/></Card>{selected&&kind==='sessions'&&<>{list.data?.items?.find((s:Data)=>s.id===selected)?.projectedEvents>0&&<CompressionList key={'c'+selected} scopeId={scopeId} sessionId={selected} openEvent={openEvent}/>}<Evidence key={selected} scopeId={scopeId} sessionId={selected} openEvent={openEvent}/></>} {selected&&kind==='chains'&&<Card title="关联链详情"><RequestState {...chain} retry={()=>void chain.load()}/>{chain.data&&<><Facts data={{id:chain.data.id??chain.data.chain?.id,status:chain.data.status??chain.data.chain?.status}}/><div className="chain-members">{(chain.data.events??chain.data.members??chain.data.eventIds??chain.data.chain?.eventIds??[]).map((e:Data|string,i:number)=>{const id=typeof e==='string'?e:e.id??e.eventId;return <button key={id??i} onClick={()=>openEvent(id)}><span>{i+1}</span><strong>{typeof e==='string'?short(e):e.toolName??e.tool??short(id)}</strong><small>{id}</small><b>→</b></button>;})}</div>{chain.data.capsule&&<Capsule data={chain.data.capsule}/>} {chain.data.capsuleId&&<DerivedCapsule scopeId={scopeId} capsuleId={chain.data.capsuleId} openEvent={openEvent}/>}<JsonPanel data={chain.data} label="链来源与元数据"/></>}</Card>}</>;
